<template><OperationsFrame title="通知公告管理">
 <el-form :inline="true" v-show="showSearch"><el-form-item label="公告标题"><el-input v-model="query.keyword" clearable placeholder="请输入公告标题" @keyup.enter="search" /></el-form-item><el-form-item label="状态"><el-select v-model="query.status" clearable placeholder="全部"><el-option label="已发布" value="0" /><el-option label="草稿" value="2"/><el-option label="已撤回" value="1" /></el-select></el-form-item><el-form-item><el-button type="primary" icon="Search" @click="search">搜索</el-button><el-button icon="Refresh" @click="reset">重置</el-button></el-form-item></el-form>
 <div class="operations-toolbar"><el-button type="primary" plain icon="Plus" @click="edit()">新增</el-button><right-toolbar v-model:showSearch="showSearch" @queryTable="load" /></div>
 <el-table :data="rows" v-loading="loading"><el-table-column prop="noticeId" label="编号" width="85" /><el-table-column prop="noticeTitle" label="公告标题" min-width="270" show-overflow-tooltip /><el-table-column label="类型" width="95"><template #default="{row}">{{noticeTypes.find(x=>x.dictValue===row.noticeType)?.dictLabel || row.noticeType}}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.status==='0'?'success':'info'">{{row.status==='0'?'已发布':row.status==='2'?'草稿':'已撤回'}}</el-tag></template></el-table-column><el-table-column prop="readCount" label="已读人数" width="100" /><el-table-column prop="createBy" label="发布账号" min-width="120" /><el-table-column :formatter="formatPlatformTime" prop="createTime" label="创建时间" width="180" /><el-table-column label="操作" width="180" fixed="right"><template #default="{row}"><el-button link type="primary" @click="edit(row)">修改</el-button><el-button link type="primary" @click="showReaders(row)">已读</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table>
 <pagination v-show="total>0" :total="total" v-model:page="query.pageNum" v-model:limit="query.pageSize" @pagination="load" />
 <el-dialog v-model="open" :title="form.noticeId?'修改公告':'新增公告'" width="720px" class="operations-dialog"><el-form ref="formRef" :model="form" label-width="90px"><el-form-item label="公告标题" prop="noticeTitle" :rules="required"><el-input v-model="form.noticeTitle" maxlength="50" show-word-limit /></el-form-item><el-form-item label="公告类型"><el-select v-model="form.noticeType"><el-option v-for="d in noticeTypes.filter(x=>x.status==='0'||x.dictValue===form.noticeType)" :key="d.dictValue" :value="d.dictValue" :label="d.dictLabel" /></el-select></el-form-item><el-form-item label="公告内容" prop="noticeContent" :rules="required"><el-input v-model="form.noticeContent" type="textarea" :rows="10" maxlength="20000" show-word-limit /></el-form-item><el-form-item label="发布状态"><el-radio-group v-model="form.status"><el-radio value="2">草稿</el-radio><el-radio value="0">发布</el-radio><el-radio value="1">撤回</el-radio></el-radio-group></el-form-item></el-form><template #footer><el-button @click="open=false">取 消</el-button><el-button type="primary" :loading="saving" @click="save">确 定</el-button></template></el-dialog>
 <el-dialog v-model="readerOpen" title="公告阅读记录" width="650px" class="operations-dialog"><el-table :data="readers" v-loading="readerLoading"><el-table-column prop="loginName" label="账号ID" min-width="130" /><el-table-column prop="userName" label="账号名称" min-width="130" /><el-table-column :formatter="formatPlatformTime" prop="readTime" label="阅读时间" width="180" /></el-table><pagination v-show="readerTotal>0" :total="readerTotal" v-model:page="readerQuery.pageNum" v-model:limit="readerQuery.pageSize" @pagination="loadReaders" /></el-dialog>
</OperationsFrame></template>
<script setup>
import {formatPlatformTime} from '@/utils/platformTime'

import {useDisplayDictionary} from './useDisplayDictionary'
const noticeTypes = useDisplayDictionary('notice_type')
import {ref,reactive} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import OperationsFrame from './OperationsFrame.vue';import {useOperations} from './useOperations';import {getOperation,listOperation,createOperation,updateOperation,removeOperation} from '@/api/operations';
const {rows,total,loading,query,showSearch,load,search,reset}=useOperations('notices',{keyword:'',status:''});const open=ref(false),saving=ref(false),formRef=ref(),form=reactive({}),readerOpen=ref(false),readerLoading=ref(false),readers=ref([]),readerTotal=ref(0),readerQuery=reactive({pageNum:1,pageSize:20}),readerNotice=ref(null),required=[{required:true,message:'此项不能为空',trigger:'blur'}]
async function edit(row){try{Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,row?(await getOperation('notices',row.noticeId)).data:{noticeTitle:'',noticeType:'1',noticeContent:'',status:'2',remark:''});open.value=true;formRef.value?.clearValidate()}catch{}}
async function save(){if(!await formRef.value.validate().catch(()=>false))return;saving.value=true;try{if(form.noticeId)await updateOperation('notices',form.noticeId,form);else await createOperation('notices',form);open.value=false;ElMessage.success('公告已保存');await load()}catch{}finally{saving.value=false}}
async function remove(row){try{await ElMessageBox.confirm(`删除公告「${row.noticeTitle}」及其阅读记录？`,'删除公告',{type:'warning'});await removeOperation('notices',row.noticeId);await load();ElMessage.success('公告已删除')}catch{}}
async function showReaders(row){readerNotice.value=row.noticeId;readerQuery.pageNum=1;readerOpen.value=true;await loadReaders()}
async function loadReaders(){readerLoading.value=true;try{const r=await listOperation(`notices/${readerNotice.value}/readers`,readerQuery);readers.value=r.rows;readerTotal.value=r.total}catch{}finally{readerLoading.value=false}}
</script>
